from typing import List


def split_identifier(name: str) -> List[str]:
    # Replace separators
    s = name
    for c in '_-.':
        s = s.replace(c, ' ')

    words = []
    current = ''

    for i in range(len(s)):
        char = s[i]
        if char.isspace():
            if current:
                words.append(current.lower())
                current = ''
            continue

        if i > 0:
            prev = s[i-1]
            # Rule: lowercase/digit followed by uppercase
            if char.isupper() and (prev.islower() or prev.isdigit()):
                if current:
                    words.append(current.lower())
                    current = ''
            # Rule: Acronyms - uppercase run followed by lowercase
            elif char.islower() and prev.isupper():
