from typing import List
from .normalize_whitespace import normalize_whitespace

def split_sentences(text: str) -> List[str]:
    if not text:
        return []
    cleaned_text = normalize_whitespace(text)
    if not cleaned_text:
        return []
    words = cleaned_text.split()
    if not words:
        return []
    abbreviations = {'Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.', 'St.', 'vs.', 'e.g.', 'i.e.'}
    sentences = []
    current_sentence = []
    for i in range(len(words)):
        word = words[i]
        current_sentence.append(word)
        if i == len(words) - 1:
            break
        next_word = words[i + 1]
        if word in abbreviations:
            continue
        if len(word) == 2 and word[1] == '.' and word[0].isupper():
            continue
        if len(word) == 3 and word[2] == '.' and word[1].isupper() and word[0] in "'([":
            continue
        terminators = '.!?'
        closers = "' )]"
        has_boundary = False
        if word:
            last_char = word[-1]
            if last_char in terminators:
                has_boundary = True
            elif last_char in closers and len(word) > 1 and word[-2] in terminators:
                has_boundary = True
        if has_boundary:
            openers = "' (["
            if next_word and (next_word[0].isupper() or next_word[0].isdigit() or next_word[0] in openers):
                sentences.append(' '.join(current_sentence))
                current_sentence = []
    if current_sentence:
        sentences.append(' '.join(current_sentence))
    return sentences
"}}}
