    sentences = []
    current_sentence = []
    for i in range(len(words)):
        word = words[i]
        current_sentence.append(word)
        if i == len(words) - 1:
            break
        next_word = words[i + 1]
        if word in abbreviations:
            continue
        if len(word) == 2 and word[1] == '.' and word[0].isupper():
            continue
        if len(word) == 3 and word[2] == '.' and word[1].isupper() and word[0] in "'([":
            continue

        # Check if word ends with a terminator run optionally followed by closers
        terminators = '.!?'
        closers = "' )]"

        # Strip trailing closers to find the terminator run
        stripped = word
        while stripped and stripped[-1] in closers:
            stripped = stripped[:-1]

        has_boundary = False
        if stripped and stripped[-1] in terminators:
            has_boundary = True

        if has_boundary:
            openers = "' (["
            if next_word and (next_word[0].isupper() or next_word[0].isdigit() or next_word[0] in openers):
                sentences.append(' '.join(current_sentence))
                current_sentence = []
    if current_sentence:
        sentences.append(' '.join(current_sentence))
    return sentences
"}}}
